export type MaterialType = "LUPULO" | "MALTA" | "YEAST" | "ADJUNTO" | "OTRO";
export type AlertStatus = "CRITICAL" | "RED" | "YELLOW" | "GREEN" | "NONE";
export type ActionStatus = "ORDER_NOW" | "ORDER_SOON" | "COVERED" | "OK";
export type ProductionStatus = "PENDING" | "IN_PROGRESS" | "COMPLETED" | "CANCELLED";
export type OrderStatus =
  | "PENDING"
  | "IN_TRANSIT"
  | "RECEIVED_COMPLETE"
  | "RECEIVED_PARTIAL"
  | "CANCELLED";
export type PaymentMethod =
  | "TRANSFER"
  | "SUPPLIER_CREDIT"
  | "CASH"
  | "CARD"
  | "OTHER";
export type ReceptionCondition =
  | "GOOD"
  | "REGULAR"
  | "DAMAGED"
  | "INCOMPLETE"
  | "EXPIRED";

export type Role = "DEVELOPER" | "SUPERVISOR" | "OPERATOR" | "TRANSPORTER";
export type ApprovalStatus = "PENDING" | "APPROVED" | "REJECTED";
export type BlockType = "EMAIL" | "IP";

export interface SettingDef {
  key: string;
  label: string;
  description?: string;
  valueType: "number" | "boolean" | "string" | "select";
  defaultValue: string;
  value: string;
  editableByRole: "DEVELOPER" | "SUPERVISOR";
  options?: string[];
  min?: number;
  max?: number;
  isDefault?: boolean;
  updatedAt?: string | null;
}

export type SettingsMap = Record<string, SettingDef[]>;

export type JitStatus = "CRITICAL" | "RED" | "YELLOW" | "GREEN" | "NONE";

export interface CalendarPlan {
  id: string;
  style: string;
  batches: number;
  jitStatus: JitStatus;
  hasCritical: boolean;
  approvalStatus: string;
  productionStatus: string;
}

export interface ProductionCalendarDay {
  date: string;
  highestStatus: JitStatus;
  hasCritical: boolean;
  plansCount: number;
  plans: CalendarPlan[];
}

export interface ProductionCalendar {
  month: string;
  days: ProductionCalendarDay[];
}

export interface AuditChange {
  field: string;
  label: string;
  oldValue: any;
  newValue: any;
  unit?: string;
}

export interface AuditLog {
  id: string;
  userId: string | null;
  user: { id: string; name: string | null; email: string; role: Role } | null;
  action: string;
  entityType: string;
  entityId: string | null;
  entityName: string | null;
  description: string | null;
  ipAddress: string | null;
  changes: AuditChange[] | null;
  metadata: Record<string, any> | null;
  createdAt: string;
}

export interface AuditGroupedUser {
  userId: string | null;
  user: { id: string; name: string | null; email: string; role: Role } | null;
  count: number;
  lastActivity: string | null;
}

export interface Supplier {
  id: string;
  name: string;
  country: string | null;
  materialType: string | null;
  daysToOrder: number;
  estimatedDeliveryDays: number;
  minOrderQuantity: number | null;
  minOrderUnit: string | null;
  hasCredit: boolean;
  notes: string | null;
}

export interface Material {
  id: string;
  name: string;
  type: MaterialType;
  brand: string | null;
  unit: string;
  unitPrice: number;
  priceUnit: string | null;
  supplierId: string | null;
  supplier?: Supplier | null;
  inventory?: InventoryRow | null;
}

export interface ProductionRequirement {
  id: string;
  productionPlanId: string;
  inventoryId: string;
  materialId: string;
  material?: { name: string; unit: string };
  productionPlan?: { id: string; style: string; productionDate: string } | null;
  requiredQuantity: number;
  reservedQuantity: number;
  missingQuantity: number;
  isCritical: boolean;
  actionStatus: ActionStatus;
  linkedOrderId: string | null;
  linkedOrder?: {
    id: string;
    folio: string;
    estimatedArrivalDate: string | null;
    status: OrderStatus;
  } | null;
}

export interface InventoryRow {
  id: string;
  materialId: string;
  material?: Material;
  currentStock: number;
  reservedStock: number;
  alertStatus: AlertStatus;
  isCritical: boolean;
  notes: string | null;
  updatedAt: string;
  requirements?: ProductionRequirement[];
}

export interface ProductionPlan {
  id: string;
  productionDate: string;
  style: string;
  plannedBatches: number;
  maltKgPerBatch: number;
  hopKgPerBatch: number;
  yeastGPerBatch: number;
  totalMaltKg: number;
  totalHopKg: number;
  totalYeastG: number;
  notes: string | null;
  orderedAt: string | null;
  signedOffAt: string | null;
  approvalStatus: ApprovalStatus;
  productionStatus: ProductionStatus;
  approvedById: string | null;
  approvedAt: string | null;
  rejectedById: string | null;
  rejectedAt: string | null;
  rejectionReason: string | null;
  hasMissingPrices: boolean;
  estimatedCost: number;
  createdById: string | null;
  createdAt: string;
  requirements?: ProductionRequirement[];
  hasCriticalRequirements?: boolean;
}

export interface Order {
  id: string;
  folio: string;
  orderDate: string;
  materialId: string;
  material?: Material;
  supplierId: string | null;
  supplier?: Supplier | null;
  productionPlanId: string | null;
  productionPlan?: { id: string; style: string; productionDate: string } | null;
  orderedQuantity: number;
  totalPaid: number | null;
  paymentMethod: PaymentMethod | null;
  estimatedArrivalDate: string | null;
  status: OrderStatus;
  month: string;
  notes: string | null;
  receptions?: Reception[];
  createdAt: string;
}

export interface Reception {
  id: string;
  receptionDate: string;
  orderId: string;
  order?: Order;
  receivedQuantity: number;
  condition: ReceptionCondition;
  isConforming: boolean;
  batchLot: string | null;
  receivedBy: string | null;
  notes: string | null;
  createdAt: string;
}

export interface StyleMeta {
  name: string;
  imageUri: string | null;
}

export interface RecipeLine {
  id: string;
  beerStyle: string;
  materialId: string;
  material?: Material;
  qtyPerBatch: number;
  notes: string | null;
}

export interface OrderPreviewItem {
  materialId: string;
  materialName: string;
  unit: string;
  requiredQuantity: number;
  currentStock: number;
  reservedByOthers: number;
  incomingQuantity: number;
  missingQuantity: number;
  isCritical: boolean;
  alertStatus: AlertStatus | null;
  actionStatus: ActionStatus;
  supplierId: string | null;
  supplierName: string | null;
  estimatedCost: number;
  willOrder: boolean;
}

export interface GenerateOrdersPreview {
  plan: ProductionPlan;
  preview: OrderPreviewItem[];
  totalEstimatedCost: number;
}

export interface RequirementAnalysis {
  materialId: string;
  materialName: string;
  unit: string;
  requiredQuantity: number;
  currentStock: number;
  reservedByOthers: number;
  incomingQuantity: number;
  effectiveAvailable: number;
  missingQuantity: number;
  isCritical: boolean;
  actionStatus: ActionStatus;
  bestExpectedDelivery: string | null;
  supplierName: string | null;
  daysToOrder: number;
}

export interface JITSummary {
  requirements: {
    orderNow: number;
    orderSoon: number;
    covered: number;
    ok: number;
  };
  criticalItems: InventoryRow[];
  urgentPlans: ProductionPlan[];
}

export interface DashboardSummary {
  alerts: { red: number; yellow: number; green: number; none: number; critical: number; ok: number };
  totalMaterials: number;
  upcoming: {
    plans: (ProductionPlan & { hasCriticalRequirements: boolean })[];
    batches: number;
    maltKg: number;
    hopKg: number;
    materialKg: number;
    materialType: string;
  };
  monthlySpend: { total: number; orderCount: number };
  inTransitOrders: number;
}

export interface AppUser {
  id: string;
  email: string;
  name: string | null;
  role: Role;
  isActive: boolean;
  createdAt: string;
  createdById: string | null;
}

export interface BlockedEntity {
  id: string;
  type: BlockType;
  value: string;
  reason: string | null;
  createdAt: string;
}

export interface ImportResult {
  updated: number;
  errors: { row: number; id: string; reason: string }[];
  total: number;
}
